-- Offered per salon (Kate, 28 Oct 2026): the discounts and offers each salon gives, from the SALON DISCOUNTS Google Sheet (2026 tabs, Affiliate program tab and the
-- INACTIVE tabs), shown on the Discounts and Vouchers page above the Phorest list. Belle asked for it on 28 Oct 2026.
--
-- salon_offers: one row per organisation or partner per branch. state: act (on the 2026 list), cf (still for confirmation) or off (not on the 2026 list any more,
--   or its validity has ended; shown as Inactive). phorest: ok = set up as an active discount in Phorest, arc = only archived there, no = not in Phorest, cf = to confirm,
--   empty = no match (inactive rows only; an inactive row marked ok is still live in Phorest). branch: SAA, KCA, MC, AQ, or FRA (Fratelli, closed).
--   No client names: partners, schools, companies and affiliate partners only. The sheet's Tara's Instagram promotion block (names and phone numbers) is not read.
-- Row level security with no policies: only the two security definer functions below touch it.
-- salon_offers_report(): Level 2 and above. salon_offers_import(): replaces the whole list, same push pass as the other pushers (the sheet is the source).

create table if not exists public.salon_offers (
  id bigint generated always as identity primary key,
  branch text not null,
  offer text,
  who text not null,
  stylist text,
  rule text,
  state text not null check (state in ('act', 'cf', 'off')),
  phorest text,
  pulled_at timestamptz not null default now()
);
alter table public.salon_offers enable row level security;

create or replace function public.salon_offers_report() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare out jsonb;
begin
  if coalesce((select m.level from public.dashboard_me() m limit 1), 0) < 2 then raise exception 'Level 2 and above'; end if;
  select jsonb_build_object(
    'at', coalesce((select max(pulled_at) from public.salon_offers), now()),
    'offers', coalesce((
      select jsonb_agg(jsonb_build_array(branch, coalesce(offer, ''), who, coalesce(stylist, ''), coalesce(rule, ''), state, coalesce(phorest, ''))
                       order by array_position(array['SAA','KCA','MC','AQ','FRA'], branch), array_position(array['act','cf','off'], state), id)
      from public.salon_offers), '[]'::jsonb)
  ) into out;
  return out;
end $$;
revoke all on function public.salon_offers_report() from public, anon;
grant execute on function public.salon_offers_report() to authenticated;

create or replace function public.salon_offers_import(p_pass uuid, p_rows jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare n int := 0;
begin
  if not exists (select 1 from push_passes where token = p_pass and active) then raise exception 'bad pass'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'rows must be a non-empty array'; end if;
  delete from salon_offers where true;
  insert into salon_offers (branch, offer, who, stylist, rule, state, phorest)
    select x->>'branch', x->>'offer', x->>'who', x->>'stylist', x->>'rule', x->>'state', x->>'phorest' from jsonb_array_elements(p_rows) x;
  get diagnostics n = row_count;
  return jsonb_build_object('offers', n);
end $$;
revoke all on function public.salon_offers_import(uuid, jsonb) from public;
grant execute on function public.salon_offers_import(uuid, jsonb) to anon;

